const planOut = $('Supabase V3 - Company Discovery Plan').first().json || {};
const qaOut = $('Supabase V3 - QA Baseline').first().json || {};

function assertBroker(out, rpc) {
  if (out.broker !== 'supabase') {
    throw new Error(`GTM05 FINAL expected supabase broker for ${rpc}`);
  }
  if (out.broker_version !== 'SB-BROKER-V3.0.0') {
    throw new Error(`GTM05 FINAL expected SB-BROKER-V3.0.0, got ${out.broker_version}`);
  }
  if (out.rpc_name !== rpc) {
    throw new Error(`GTM05 FINAL RPC mismatch: expected ${rpc}, got ${out.rpc_name}`);
  }
  return Array.isArray(out.response) ? out.response : [];
}

const plan = assertBroker(planOut, 'gtm_contact_company_discovery_plan_v1');
const qaRows = assertBroker(qaOut, 'gtm_project01_qa_report_v1');

if (plan.length !== 5) {
  throw new Error(`GTM05 FINAL expected 5 company discovery rows, got ${plan.length}`);
}
if (qaRows.length !== 1) {
  throw new Error(`GTM05 FINAL expected one QA row, got ${qaRows.length}`);
}

const expectedSeniorities = [
  'Founder/Owner',
  'C-Suite',
  'Partner',
  'Vice President',
  'Head',
  'Director',
  'Manager'
];

const accountIds = new Set();
const searchKeys = new Set();
const ranks = [];

for (const row of plan) {
  if (!row.account_id || !row.company_name || !row.normalized_domain || !row.search_key) {
    throw new Error('GTM05 FINAL plan contains a row missing account/company/domain/search_key');
  }

  if (row.persona_group !== 'seniority_discovery') {
    throw new Error(`GTM05 FINAL expected seniority_discovery, got ${row.persona_group}`);
  }

  if (Number(row.search_order) !== 1) {
    throw new Error(`GTM05 FINAL expected search_order=1 for ${row.company_name}`);
  }

  const seniorities = Array.isArray(row.seniority_filters) ? row.seniority_filters : [];
  if (
    seniorities.length !== expectedSeniorities.length ||
    expectedSeniorities.some(x => !seniorities.includes(x))
  ) {
    throw new Error(`GTM05 FINAL seniority filter mismatch for ${row.company_name}`);
  }

  accountIds.add(row.account_id);
  searchKeys.add(row.search_key);
  ranks.push(Number(row.account_priority_rank));
}

if (accountIds.size !== 5 || searchKeys.size !== 5) {
  throw new Error('GTM05 FINAL plan is not one deterministic search per eligible account');
}

ranks.sort((a,b) => a-b);
if (JSON.stringify(ranks) !== JSON.stringify([1,2,3,4,5])) {
  throw new Error(`GTM05 FINAL expected priority ranks 1..5, got ${ranks.join(',')}`);
}

const qa = qaRows[0];

if (qa.state !== 'PRE_SEND_CONTROLLED' || qa.all_checks_pass !== true) {
  throw new Error(`GTM05 FINAL baseline QA is not green: ${qa.state}`);
}

return [{
  json: {
    gtm05_final_dry_run_completed: true,
    acquisition_contract_version: 'CA-V1.1.0-COMPANY',
    strategy: 'company_domain_plus_seniority_then_local_persona',
    provider: 'prospeo',

    eligible_accounts: accountIds.size,
    planned_searches: plan.length,
    one_search_per_account: true,
    priority_ranks: ranks,
    seniority_filters: expectedSeniorities,

    pre_enrichment_only: true,
    email_reveal_allowed: false,
    mobile_reveal_allowed: false,

    provider_http_call_performed: false,
    provider_credits_spent: 0,
    database_mutation_performed: false,

    current_qa_state: qa.state,
    current_qa_all_checks_pass: qa.all_checks_pass,

    supabase_broker_v3_passed: true,
    supabase_workflow_id: 'SUPABASE_BROKER_V3_WORKFLOW_ID',

    live_entrypoint_configured: true,
    live_entrypoint_requires_exact_confirmation: 'EXECUTE_PROSPEO',

    gtm05_final_dry_run_all_checks_pass: true,

    next_action:
      'Keep live execution disabled for the frozen pilot. GTM05 FINAL is ready for controlled per-account acquisition when expansion begins.'
  }
}];

const input = $input.first().json || {};

const rank = Number(input.account_priority_rank);
const runMode = String(input.run_mode || 'pilot').trim().toLowerCase();
const confirmation = String(input.execute_provider_call || '').trim();

if (!Number.isInteger(rank) || rank < 1) {
  throw new Error('GTM05 FINAL account_priority_rank must be an integer >= 1');
}

if (!['pilot','full','replay'].includes(runMode)) {
  throw new Error(`GTM05 FINAL unsupported run_mode: ${runMode}`);
}

if (confirmation !== 'EXECUTE_PROSPEO') {
  throw new Error(
    'GTM05 FINAL live provider call blocked. execute_provider_call must equal EXECUTE_PROSPEO exactly.'
  );
}

return [{
  json: {
    account_priority_rank: rank,
    run_mode: runMode,
    provider_name: 'prospeo',
    provider_contract_version: 'CA-V1.1.0-COMPANY',
    max_person_per_company: 25,
    live_provider_call_confirmed: true
  }
}];

const cfg = $('Validate Explicit Live Confirmation').first().json;
const out = $input.first().json || {};

if (out.broker !== 'supabase' || out.broker_version !== 'SB-BROKER-V3.0.0') {
  throw new Error('GTM05 FINAL company discovery seed did not return from Supabase V3');
}
if (out.rpc_name !== 'gtm_seed_contact_company_discovery_run_v1') {
  throw new Error(`GTM05 FINAL seed RPC mismatch: ${out.rpc_name}`);
}

const rows = Array.isArray(out.response) ? out.response : [];
if (rows.length !== 1 || !rows[0]?.run_id) {
  throw new Error('GTM05 FINAL company discovery seed returned no canonical run');
}

return [{
  json: {
    ...cfg,
    acquisition_run_id: rows[0].run_id,
    acquisition_run_key: rows[0].run_key,
    eligible_account_count: Number(rows[0].eligible_account_count),
    planned_search_count: Number(rows[0].planned_search_count),
    newly_inserted_search_count: Number(rows[0].newly_inserted_search_count),
    existing_search_count: Number(rows[0].existing_search_count)
  }
}];

const cfg = $('Validate Seed Result').first().json;
const out = $input.first().json || {};

if (out.broker !== 'supabase' || out.broker_version !== 'SB-BROKER-V3.0.0') {
  throw new Error('GTM05 FINAL provider-search claim did not return from Supabase V3');
}
if (out.rpc_name !== 'gtm_claim_contact_provider_search_v1') {
  throw new Error(`GTM05 FINAL claim RPC mismatch: ${out.rpc_name}`);
}

const rows = Array.isArray(out.response) ? out.response : [];
if (rows.length !== 1) {
  throw new Error(
    `GTM05 FINAL expected exactly one claimed provider search, got ${rows.length}`
  );
}

const claim = rows[0];

if (
  !claim.search_key ||
  !claim.normalized_domain ||
  !claim.company_name ||
  claim.persona_group !== 'seniority_discovery'
) {
  throw new Error('GTM05 FINAL claimed search is missing required V1.1 fields');
}

const seniorities = [
  'Founder/Owner',
  'C-Suite',
  'Partner',
  'Vice President',
  'Head',
  'Director',
  'Manager'
];

return [{
  json: {
    ...cfg,
    ...claim,
    provider_name: 'prospeo',
    provider_contract_version: 'CA-V1.1.0-COMPANY',
    seniority_filters: seniorities,
    prospeo_request_body: {
      page: 1,
      filters: {
        company: {
          websites: {
            include: [claim.normalized_domain]
          }
        },
        person_seniority: {
          include: seniorities
        },
        max_person_per_company: 25
      }
    },
    enrichment_allowed: false,
    email_reveal_allowed: false,
    mobile_reveal_allowed: false
  }
}];

const claim = $('Build Validated Prospeo Search').first().json;
const response = $input.first().json ?? {};

let providerPayload = null;

if (response?.error === false && Array.isArray(response?.results)) {
  providerPayload = response;
} else {
  const candidates = [
    response?.error?.message,
    response?.message,
    response?.body
  ].filter(v => typeof v === 'string');

  for (const text of candidates) {
    const first = text.indexOf('{');
    const last = text.lastIndexOf('}');
    if (first >= 0 && last > first) {
      const inner = text.slice(first, last + 1).replace(/\\"/g, '"');
      try {
        const parsed = JSON.parse(inner);
        if (parsed && typeof parsed === 'object') {
          providerPayload = parsed;
          break;
        }
      } catch (_) {}
    }
  }
}

const success =
  providerPayload?.error === false &&
  Array.isArray(providerPayload?.results);

const providerErrorCode =
  providerPayload?.error === true
    ? providerPayload?.error_code ?? null
    : null;

const results = success ? providerPayload.results : [];
const pagination =
  success && providerPayload.pagination
    ? providerPayload.pagination
    : null;

const freeSearch =
  success ? Boolean(providerPayload.free) : null;

const statusCandidate = [
  response?.error?.status,
  response?.statusCode,
  response?.status
].find(v => Number.isInteger(Number(v)));

let httpStatus =
  success
    ? 200
    : statusCandidate !== undefined
      ? Number(statusCandidate)
      : null;

let finishStatus;
let errorCode = null;
let errorMessage = null;
let nextRetryAt = null;

if (success) {
  finishStatus = results.length > 0 ? 'succeeded' : 'no_results';
} else if (providerErrorCode === 'NO_RESULTS') {
  finishStatus = 'no_results';
  errorCode = 'NO_RESULTS';
  errorMessage = 'Prospeo returned NO_RESULTS for company seniority discovery.';
  if (httpStatus === null) httpStatus = 400;
} else {
  errorCode = String(
    providerErrorCode ??
    response?.error?.code ??
    'PROSPEO_UNPARSED_ERROR'
  );

  errorMessage = String(
    providerPayload?.filter_error ??
    providerPayload?.message ??
    response?.error?.message ??
    response?.message ??
    'Prospeo returned an unparsed error'
  ).slice(0, 2000);

  if (httpStatus === 429 || (httpStatus !== null && httpStatus >= 500)) {
    finishStatus = 'retryable_failed';
    nextRetryAt =
      new Date(Date.now() + 60 * 60 * 1000).toISOString();
  } else {
    finishStatus = 'permanent_failed';
  }
}

const normalizedPeople = results.map((entry, index) => {
  const p = entry?.person ?? {};
  const c = entry?.company ?? {};

  return {
    result_rank: index + 1,
    provider_contact_id: p.person_id ?? null,
    first_name: p.first_name ?? null,
    last_name: p.last_name ?? null,
    full_name: p.full_name ?? null,
    job_title: p.current_job_title ?? null,
    seniority: p.seniority ?? p.current_job_seniority ?? null,
    headline: p.headline ?? null,
    linkedin_url: p.linkedin_url ?? null,
    company_name: c.name ?? c.company_name ?? null,
    company_website: c.website ?? c.domain ?? null,
    company_id: c.company_id ?? null,
    email_status_preview: p?.email?.status ?? null,
    email_revealed: Boolean(p?.email?.revealed),
    mobile_status_preview: p?.mobile?.status ?? null,
    mobile_revealed: Boolean(p?.mobile?.revealed)
  };
});

if (
  normalizedPeople.some(p =>
    p.email_revealed === true ||
    p.mobile_revealed === true
  )
) {
  finishStatus = 'permanent_failed';
  errorCode = 'PRE_ENRICHMENT_REVEAL_VIOLATION';
  errorMessage =
    'Provider response unexpectedly contained revealed email/mobile data during acquisition.';
}

return [{
  json: {
    ...claim,

    finish_status: finishStatus,
    provider_result_count: results.length,
    last_http_status: httpStatus,
    last_error_code: errorCode,
    last_error_message: errorMessage,
    next_retry_at: nextRetryAt,

    prospeo_free_search: freeSearch,
    prospeo_pagination: pagination,
    normalized_people: normalizedPeople,

    provider_call_performed: true,

    finish_response_metadata: {
      stage: 'GTM05_FINAL',
      strategy: 'company_domain_plus_seniority_then_local_persona',
      query_domain: claim.normalized_domain,
      seniority_filters: claim.seniority_filters,
      returned_people: results.length,
      free_search: freeSearch,
      pagination,
      enrichment_called: false,
      email_reveal_allowed: false,
      mobile_reveal_allowed: false,
      normalized_people: normalizedPeople
    }
  }
}];

const normalized =
  $('Normalize Prospeo Response - Never Reset Attempt').first().json;

const finishOut =
  $('Supabase V3 - Finish Provider Attempt').first().json || {};

const ingestOut = $input.first().json || {};

if (
  finishOut.broker !== 'supabase' ||
  finishOut.broker_version !== 'SB-BROKER-V3.0.0' ||
  finishOut.rpc_name !== 'gtm_finish_contact_provider_search_v1'
) {
  throw new Error('GTM05 FINAL provider finish ledger validation failed');
}

const finishRows = Array.isArray(finishOut.response)
  ? finishOut.response
  : [];

if (finishRows.length !== 1) {
  throw new Error(`GTM05 FINAL expected one finish row, got ${finishRows.length}`);
}

if (
  ingestOut.broker !== 'supabase' ||
  ingestOut.broker_version !== 'SB-BROKER-V3.0.0' ||
  ingestOut.rpc_name !== 'gtm_ingest_contact_provider_results_v1'
) {
  throw new Error(
    'GTM05 FINAL provider result ingest failed after the provider attempt was already durably recorded.'
  );
}

const ingestRows = Array.isArray(ingestOut.response)
  ? ingestOut.response
  : [];

if (ingestRows.length !== 1 || !ingestRows[0]?.search_id) {
  throw new Error(
    'GTM05 FINAL provider result ingest returned no canonical ingestion row. Do NOT repeat the provider call; replay normalized results from ledger metadata.'
  );
}

const ingest = ingestRows[0];

return [{
  json: {
    gtm05_live_acquisition_completed: true,

    provider: 'prospeo',
    acquisition_contract_version: 'CA-V1.1.0-COMPANY',
    strategy: 'company_domain_plus_seniority_then_local_persona',

    company_name: normalized.company_name,
    normalized_domain: normalized.normalized_domain,
    account_priority_rank: normalized.account_priority_rank,

    search_key: normalized.search_key,
    provider_search_status: finishRows[0].status,
    attempt_count: finishRows[0].attempt_count,

    provider_call_performed: true,
    provider_result_count: normalized.provider_result_count,

    observation_inserted_count: Number(ingest.observation_inserted_count),
    observation_updated_count: Number(ingest.observation_updated_count),
    eligible_count: Number(ingest.eligible_count),
    ineligible_count: Number(ingest.ineligible_count),
    contact_inserted_count: Number(ingest.contact_inserted_count),
    contact_matched_updated_count: Number(ingest.contact_matched_updated_count),
    canonical_contact_count: Number(ingest.canonical_contact_count),

    enrichment_called: false,
    email_reveal_allowed: false,
    mobile_reveal_allowed: false,

    supabase_broker_v3_passed: true,

    next_action:
      'Run GTM06 FINAL only for verified-email enrichment candidates. Do not reveal mobile.'
  }
}];

const normalized =
  $('Normalize Prospeo Response - Never Reset Attempt').first().json;

const finishOut =
  $('Supabase V3 - Finish Provider Attempt').first().json || {};

if (
  finishOut.broker !== 'supabase' ||
  finishOut.broker_version !== 'SB-BROKER-V3.0.0' ||
  finishOut.rpc_name !== 'gtm_finish_contact_provider_search_v1'
) {
  throw new Error('GTM05 FINAL non-success finish ledger validation failed');
}

const rows = Array.isArray(finishOut.response)
  ? finishOut.response
  : [];

if (rows.length !== 1) {
  throw new Error(`GTM05 FINAL expected one finish row, got ${rows.length}`);
}

return [{
  json: {
    gtm05_live_acquisition_completed: true,

    provider: 'prospeo',
    acquisition_contract_version: 'CA-V1.1.0-COMPANY',
    strategy: 'company_domain_plus_seniority_then_local_persona',

    company_name: normalized.company_name,
    normalized_domain: normalized.normalized_domain,
    account_priority_rank: normalized.account_priority_rank,

    search_key: normalized.search_key,
    provider_search_status: rows[0].status,
    attempt_count: rows[0].attempt_count,

    provider_call_performed: true,
    provider_result_count: normalized.provider_result_count,

    enrichment_called: false,
    contacts_inserted: false,

    error_code: normalized.last_error_code,
    error: normalized.last_error_message,
    next_retry_at: normalized.next_retry_at,

    next_action:
      normalized.finish_status === 'no_results'
        ? 'No eligible provider results were returned. Do not spend an enrichment credit.'
        : normalized.finish_status === 'retryable_failed'
          ? 'Wait until next_retry_at, then claim the same ledger task. Attempt history must remain intact.'
          : 'Provider search failed permanently. Review the exact provider error before any retry.'
  }
}];
